{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "In rodents and non-human primates, [11C]PHXY, a 1-methyl-4-substituted tetrahydropyridine closely analogous to the query, freely crosses the BBB after i.v. injection, directly supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "The 1-methyl-1,2,3,6-tetrahydropyridin-4-yl ether [11C]COU also freely crosses the BBB in rodents and non-human primates, reinforcing that this tetrahydropyridine scaffold is brain-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A tetrahydropyridine derivative (ALX-1175) showed excellent brain exposure with a brain/plasma ratio of 43 in rats, demonstrating high CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "[11C]Toluene, a small lipophilic aromatic molecule sharing the phenyl substituent, shows rapid brain uptake in baboon PET studies, supporting passive BBB permeation of the phenyl-bearing query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is 1-methyl-4-phenyl-1,2,3,6-tetrahydropyridine (MPTP), a small lipophilic tetrahydropyridine. Direct in vivo evidence from closely related 1-methyl-4-substituted tetrahydropyridines shows free BBB crossing, and another tetrahydropyridine derivative achieved excellent brain exposure. These transferable experimental results strongly outweigh the single low-uptake piperidine amide analogue.",
  "evidence_gaps": [
    "No direct MPTP-specific quantitative brain/plasma measurement is included in the retrieved evidence, but close tetrahydropyridine analogues provide direct transferable in vivo data.",
    "One piperidine amide analogue (C15) showed low brain uptake, but its larger polar structure is not representative of the small lipophilic tetrahydropyridine query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

